import{_ as s,c as n,a as i,o as t}from"./app-C_dHcy8Q.js";const a={};function l(o,e){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="assignments-per-game-env-function-sets" tabindex="-1"><a class="header-anchor" href="#assignments-per-game-env-function-sets"><span>Assignments (Per Game/Env Function Sets)</span></a></h1><p>This document describes a minimal control-plane for function assignments per game/env. It is an early building block for M5 (pack downlink &amp; hot update).</p><p>Concept</p><ul><li>Assignments is a mapping from <code>game_id|env</code> to an array of <code>function_id</code>s.</li><li>Server persists this mapping to <code>&lt;packDir&gt;/assignments.json</code> and exposes HTTP APIs to get/set it.</li><li>Agents can later poll this mapping to decide which adapters/packs to activate (future work).</li></ul><p>Server APIs</p><ul><li>GET <code>/api/assignments?game_id=&amp;env=</code><ul><li>Returns <code>{ assignments: { &quot;&lt;game&gt;|&lt;env&gt;&quot;: [&quot;fn1&quot;,&quot;fn2&quot;,...] } }</code>.</li><li>Filters are optional; when omitted, returns all entries.</li></ul></li><li>POST <code>/api/assignments</code><ul><li>Body: <code>{ &quot;game_id&quot;: &quot;&lt;game&gt;&quot;, &quot;env&quot;: &quot;&lt;env&gt;&quot;, &quot;functions&quot;: [&quot;fn1&quot;,&quot;fn2&quot;] }</code></li><li>Overwrites the mapping for the given key; persists to <code>assignments.json</code>.</li><li>Response: <code>{ ok: true, unknown: [&quot;fnX&quot;, ...] }</code> where <code>unknown</code> lists function ids that are not present in the current descriptors and were ignored.</li></ul></li></ul><p>CLI</p><ul><li>List assignments:</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">./bin/croupier assignments list --api http://localhost:8080</span>
<span class="line">./bin/croupier assignments list --game_id mygame --env prod --api http://localhost:8080</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>Set assignments:</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">./bin/croupier assignments set \\</span>
<span class="line">  --game_id mygame --env prod \\</span>
<span class="line">  --functions prom.query,prom.query_range \\</span>
<span class="line">  --api http://localhost:8080</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Web UI</p><ul><li>Configure via GM → Assignments: choose game/env and select function ids (empty means allow all). Save to persist on the server.</li><li>GM → Functions will auto-filter the function list by assignments when game/env is selected.</li></ul><p>Notes</p><ul><li>This is a minimal, file-backed control-plane intended to unblock end-to-end demos.</li><li>Future work (M5): Agent-side polling &amp; hot (un)load of adapters/packs, Server-side validation &amp; drift detection.</li></ul>`,15)])])}const c=s(a,[["render",l]]),u=JSON.parse('{"path":"/assignments.html","title":"Assignments (Per Game/Env Function Sets)","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1761994660000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"514f1b167d7492e355d07c0f3c3fcbbf44319c2a","time":1761994660000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat(agent+server+gm): Adapter supervisor, downlink verify; registry health; assignments UX; HTTP tests; docs"}]},"filePathRelative":"assignments.md"}');export{c as comp,u as data};
